void main()
{
    uvec3 gid = gl_GlobalInvocationID;
    ivec3 coord = ivec3(gid);
    ivec2 output_size = ivec2(uTDOutputInfo.res.zw);

    if (coord.x >= output_size.x || coord.y >= output_size.y)
        return;

    vec2 uv = (vec2(coord.xy) + vec2(0.5)) / vec2(output_size);
    vec4 previous = TDImageLoadOutput(0, coord);
    vec4 color = vec4(uv, 0.5 + 0.5 * sin(absTime.seconds), 1.0);

    TDImageStoreOutput(0, coord, mix(previous, color, 0.25));
}

layout(location = 0) out vec4 fragColor;

void main()
{
    int input_index = int(floor(vUV.x * float(max(TD_NUM_2D_INPUTS, 1))));
    input_index = clamp(input_index, 0, TD_NUM_2D_INPUTS - 1);

    vec2 pixel_step = uTD2DInfos[input_index].res.xy;
    vec4 center = texture(sTD2DInputs[nonuniformEXT(input_index)], vUV.st);
    vec4 right = texture(sTD2DInputs[nonuniformEXT(input_index)], vUV.st + vec2(pixel_step.x, 0.0));
    vec4 offset = textureOffset(sTD2DInputs[nonuniformEXT(input_index)], vUV.st, ivec2(0, 1));

    fragColor = TDOutputSwizzle((center + right + offset) / 3.0);
}

