// Vertex shader
out vec3 vWorldPos;
out vec3 vWorldNorm;
out vec4 vPointColor;
flat out int vCameraIndex;

void main()
{
    vec4 world_pos = TDDeform(vec4(TDPos(), 1.0));
    vWorldPos = world_pos.xyz;
    vWorldNorm = normalize(TDDeformNorm(TDNormal()));
    vPointColor = TDPointColor();
    vCameraIndex = TDCameraIndex();
    gl_Position = TDWorldToProj(world_pos);
}

// Pixel shader
in vec3 vWorldPos;
in vec3 vWorldNorm;
in vec4 vPointColor;
flat in int vCameraIndex;
layout(location = 0) out vec4 fragColor;

void main()
{
    TDCheckDiscard();
    TDCheckOrderIndTrans();

    vec3 normal = normalize(vWorldNorm);
    vec3 camera_pos = uTDMats[vCameraIndex].camInverse[3].xyz;
    vec3 view_dir = normalize(camera_pos - vWorldPos);
    vec3 lit = vec3(0.0);

    for (int i = 0; i < TD_NUM_LIGHTS; ++i)
    {
        TDPBRResult light = TDLightingPBR(i, vPointColor.rgb, vec3(1.0), vWorldPos, normal, 1.0, vec3(0.0), view_dir, 0.45);
        lit += light.diffuse + light.specular;
    }

    vec4 color = vec4(lit, vPointColor.a);
    TDAlphaTest(color.a);
    color = TDFog(color, vWorldPos, vCameraIndex);
    color = TDDither(color);
    fragColor = TDOutputSwizzle(color);
}

